def decode_sample(raw_word):
    ordered = (
        (raw_word & 0x8000)
        | ((raw_word << 8) & 0x4000)
        | ((raw_word >> 1) & 0x3F80)
        | ((raw_word << 1) & 0x007E)
        | ((raw_word >> 7) & 0x0001)
    )
    if ordered == 0:
        return 0
    sign = -1 if (ordered & 0x8000) else 1
    mag = ordered & 0x7FFF
    return sign * LOG_LUT.get(mag, 0)

def main():
    target_rom = ROM_PATH
    if not os.path.exists(target_rom):
        rom_alt = os.path.join(PROJECT_DIR, "MT32_PCM.ROM")
        if os.path.exists(rom_alt):
            target_rom = rom_alt
        else:
            print("[!] 에러: data/MT32_PCM.ROM 파일을 찾을 수 없습니다.")
            print("[*] 'data/MT32_PCM.ROM' 경로에 512KB 롬 파일을 넣어주세요.")
            sys.exit(1)

    print(f"[*] MT-32 PCM ROM 파일 읽는 중: {target_rom}")
    with open(target_rom, "rb") as f:
        data = f.read()

    if len(data) != 524288:
        print("[!] 에러: ROM 파일 크기가 524,288 바이트(512KB)가 아닙니다.")
        sys.exit(1)

    print("[*] Roland LA-32 16-bit 선형 PCM 복원 중...")
    samples = []
    for i in range(TOTAL_SAMPLES):
        raw = (data[i * 2] << 8) | data[i * 2 + 1]
        samples.append(decode_sample(raw))

    os.makedirs(os.path.dirname(CPP_PATH), exist_ok=True)
    with open(CPP_PATH, "w", encoding="utf-8") as f:
        f.write('#include "mt32_pcm_data.h"\n\n')
        f.write('// 100% Pre-decoded 16-bit Linear MT-32 PCM Attack ROM (Flash PROGMEM, 0 bytes SRAM/PSRAM, 0-Cycle CPU)\n')
        f.write('const int16_t MT32_PCM_ROM[262144] PROGMEM = {\n')
        for i in range(0, len(samples), 16):
            chunk = samples[i:i+16]
            line = ", ".join(str(s) for s in chunk)
            if i + 16 < len(samples):
                f.write("    " + line + ",\n")
            else:
                f.write("    " + line + "\n")
        f.write("};\n")

    print(f"[+] 소스코드 생성 완료: {CPP_PATH}")

if __name__ == "__main__":
    main()
